def sort_with_twos(arr: List[int]):
    @functools.lru_cache(maxsize=None)
    def dfs(n, mask):
        if not n:
            return True
        for i in range(len(arr)):
            if (mask >> i) & 1 and arr[i] > arr[(i + 1) % n]:
                return False
        for m in range(1, len(bin(n - 1)) - 2):
            if dfs(n - (1 << m), mask | (1 << m)):
                for j in range(len(arr) - (1 << m) + 1):
                    arr[j], arr[j + (1 << m)] = arr[j] - 1, arr[j + (1 << m)]
