import functools
from typing import List, Dict

@functools.lru_cache(maxsize=None)
def solve(s: str, k: int, n: int, dp: Dict[str, int] = {}):
    if n == 0:
        return 0
    key = (n, k)
    if key in dp:
        return dp[key]

    min_ops = float('inf')
    for i in range(1, n + 1):
        if s[:i] == 'B' * i:
            ops = solve(s[i:], k, n - i, dp)
            min_ops = min(min_ops, ops + 1)
        elif i >= k:
            ops = solve(s[:i] + s[i + k:], k, n - i, dp)
            min_ops = min(min_ops, ops)

    if min_ops == float('inf'):
        min_ops = 0

    dp[key] = min_ops
    return min_ops

