def solve():
    from collections import deque

    def max_heapify(arr):
        n = len(arr)
        i = n // 2
        while i > 0:
            j = i - 1
            if arr[i] < arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
            i -= 1

    def build_max_heap(arr):
        n = len(arr)
        for i in range(n, -1, -1):
            arr[0], arr[i] = arr[i], arr[0]
            max_heapify(arr[:i + 1])

    def heap_decrease_key(arr, i, new_val):
        while i > 0 and arr[i] < arr[i // 2]:
            arr[i], arr[i // 2] = arr[i // 2], arr[i]
            i //= 2

    def heap_extract_max(arr):
        n = len(arr) - 1
        arr[n], arr[0] = arr[0], arr[n]
        max_val = arr.pop()
        max_heapify(arr)
        return max_val

    def heap_increase_key(arr, i, new_val):
        while i < len(arr) and arr[i] > new_val:
            arr[i], arr[i // 2] = arr[i // 2], arr[i]
            i *= 2

    def heap_replace_min(arr, val):
        if not arr:
            return [val]
        elif arr[0] > val:
            arr[0] = val
            heapify(arr)
            return arr
        else:
