import math

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * x, y)

def mod_inverse(a, m):
    g, x, _ = extended_gcd(a, m)
    if g != 1:
        raise ValueError("No inverse exists")
    return x % m

def solve():
    t = int(input().strip())
    for _ in range(t):
        a, b = map(int, input().split())
        gcd_ab = math.gcd(a, b)
        if gcd_ab > 1:
            print(-1)
        else:
            a_inv = mod_inverse(b - a, a)
            n = (b * a_inv) % a
            print(n)

solve()
