def build_graph(towers):
    graph = collections.defaultdict(list)
    for i, tower in enumerate(towers):
        for j in range(i+1, len(towers)):
            if tower[-1] == towers[j][0]:
                graph[tower].append((towers[j], 1))
                graph[towers[j]].append((tower, -1))
    return graph

def dfs(graph, node):
    visited = set()
    stack = [node]
    while stack:
        current = stack.pop()
        if current not in visited:
            visited.add(current)
            for neighbor, weight in graph[current]:
                if weight == -1 and neighbor in visited or weight == 1 and neighbor not in visited:
                    return True
                if neighbor not in visited:
                    stack.append(neighbor)
    return False
