def bit_swap(a, i, j, b):
    a[i] ^= (1 << b)
    a[j] ^= (1 << b)

def max_diff(n, a):
    @functools.lru_cache(maxsize=None)
    def dfs(x, mask):
        if not x:
            return 0
        res = float('-inf')
        for i in range(n):
            if (a[i] & mask) == mask:
                res = max(res, dfs(x - (1 << i), mask ^ (1 << i)))
        return res

