        if (x, y) not in dp:
            if x == n - 1 or y == m - 1:
                dp[(x, y)] = {'B': True, 'T': False}
            else:
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + 2 * dx, y + 2 * dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if board[nx][ny] == '.':
                            dp[(x, y)] = dp[(nx, ny)]
                        elif board[nx][ny] == 'R':
                            dp[(x, y)] = {'B': True, 'T': False}
                            break
                dp[(x, y)] = not all(dp[k] for k in dp)
            return dp[(x, y)]
        return dp[(x, y)]

    if dfs(0, 0)['B']:
        return "Burenka"
    else:
        return "Tonya"

