def solve():
    tests = int(input())
    for _ in range(tests):
        n, m = map(int, input().split())
        graph = defaultdict(list)
        portals = set()
        visited_stanley = set()
        visited_megan = set()
        energy_stanley = 0
        energy_megan = 0

        # Add edges and portals to the graph
        for i in range(1, n+1):
            for j in range(1, m+1):
                if i > 1:
                    graph[(i-1, j)].append((i, j))
                if j > 1:
                    graph[(i, j-1)].append((i, j))
                if (i, j) != (n, m):
                    graph[(i, j)].append((i+1, j))
                    graph[(i, j)].append((i, j+1))
                if i == n and j == 1:
                    portals.add((i, j))
                if i == 1 and j == m:
                    portals.add((i, j))

        # BFS for Stanley's path
        queue = [(1, 1, 0)]
        visited_stanley.add((1, 1))
        while queue:
            u, v, e = heapq.heappop(queue)
            if (u, v) == (n, m):
                energy_stanley = e
                break
            for w in graph[(u, v)]:
                if w not in visited_stanley:
                    heapq.heappush(queue, (u, v, e+1))
                    visited_stanley.add((u, v))

        # Dijkstra's algorithm for Megan's path
        dist = {(n, 1): float('inf')}
        queue = [(n, 1, 0)]
        while queue:
            u, v, d = heapq.heappop(queue)
            if u == 1 and v == m:
                energy_megan = dist[(u, v)]
                break
            for w in graph[(u, v)]:
                if w not in visited_megan and w in portals:
                    new_dist = d + 1
                    if new_dist < dist[w]:
                        dist[w] = new_dist
                        heapq.heappush(queue, (w[0], w[1], new_dist))
                    visited_megan.add(w)

        print(energy_stanley + energy_megan)
