def make_union_find(n):
    parent = list(range(n))
    rank = [1] * n
    size = [1] * n

    def find(x):
        if x != parent[x]:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            parent[px] = py
            size[py] += size[px]
        else:
            parent[py] = px
            size[px] += size[py]
        return True

    def connected(x, y):
